# Generated by manage.py generate_test_cases.
from typing import Any

from django.contrib.auth import get_user_model
from django.contrib.contenttypes.models import ContentType

from bloomerp.automation.actions.create_object import CreateObjectExecutor
from bloomerp.models.agents import AIAgent, AIAgentAccess
from bloomerp.models.project_management.todo import Todo
from bloomerp.tests.base import (
    BloomerpWorkflowNodeTestCase,
    WorkflowNodeScenario,
)


class TestCreateObjectNode(BloomerpWorkflowNodeTestCase):
    node_id = 'CREATE_OBJECT'
    executor_class = CreateObjectExecutor


    def get_test_scenarios(self) -> list[WorkflowNodeScenario]:
        """Exercise scalar, resolved, foreign-key, and many-to-many creation values."""
        todo_content_type = ContentType.objects.get_for_model(Todo)
        user = get_user_model().objects.create_user(
            username="creator",
            password="testpassword",
        )
        other_user = get_user_model().objects.create_user(username="second-creator")
        self.access_user_ids = [str(user.pk), str(other_user.pk)]
        agent = AIAgent.objects.create(
            name="Workflow agent", provider="openai", model_identifier="example"
        )
        access_content_type = ContentType.objects.get_for_model(AIAgentAccess)
        

        return [
            WorkflowNodeScenario(
                name="Node creates an object with configured fields",
                parameters={
                    "content_type_id": todo_content_type.id,
                    "data": {"title": "Prepare report"},
                },
                output_validators=lambda output: (
                    output.get("status") == "success"
                    and Todo.objects.filter(title="Prepare report").exists()
                ),
            ),
            WorkflowNodeScenario(
                name="Node creates an object with resolved fields",
                parameters={
                    "content_type_id": todo_content_type.id,
                    "data": {"title": "{{ input.title }}"},
                },
                trigger_data={"title": "Submit report"},
                output_validators=lambda output: (
                    output.get("status") == "success"
                    and Todo.objects.filter(title="Submit report").exists()
                ),
            ),
            WorkflowNodeScenario(
                name="Node creates an object with a user relationship",
                parameters={
                    "content_type_id": todo_content_type.id,
                    "data": {
                        "title": "Review report",
                        "requested_by": user.id,
                    },
                },
                output_validators=lambda output: (
                    output.get("status") == "success"
                    and Todo.objects.filter(
                        title="Review report",
                        requested_by=user,
                    ).exists()
                ),
            ),
            WorkflowNodeScenario(
                name="Node creates an object with all selected many-to-many relations",
                parameters={
                    "content_type_id": access_content_type.id,
                    "data": {
                        "name": "Workflow access",
                        "model": str(agent.pk),
                        "users": self.access_user_ids,
                    },
                },
                output_validators=self.validate_many_to_many_creation,
            )
        ]

    def validate_many_to_many_creation(self, output: dict[str, Any]) -> bool:
        """Confirm the created object retains every requested related user."""
        self.assertEqual(output.get("status"), "success", output)
        access = AIAgentAccess.objects.get(name="Workflow access")
        self.assertCountEqual(
            [str(user_id) for user_id in access.users.values_list("pk", flat=True)],
            self.access_user_ids,
        )
        return True
